INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 32, 'theory', 'Квиз: Безопасность и итоговый экзамен');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 0, 'После копирования образа с другого сервера служба не может его прочитать, chmod и chown ничего не меняют, а в audit.log есть avc: denied с tcontext ...:default_t:s0. Что делать первым?', '["Выполнить setenforce 0 и оставить так", "Сделать модуль политики через audit2allow", "Записать правило semanage fcontext и выполнить restorecon", "Поставить права 777 на каталог"]', 2, 'Тип default_t говорит, что файл не получил свою метку. Это неверная метка, и её чинят правилом и restorecon. Модуль политики и permissive маскируют проблему.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 1, 'SELinux в режиме permissive. Что произойдёт, когда процесс нарушит политику?', '["Действие разрешено, в журнал попадёт запись AVC с permissive=1", "Действие запрещено, запись в журнал не попадёт", "Действие запрещено, и запись попадёт в журнал", "Процесс будет остановлен сигналом"]', 0, 'Разрешающий режим только пишет: действие выполняется, а поле permissive=1 показывает, что принудительного отказа не было. Так проверяют политику перед включением.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 2, 'В журнале ядра много строк apparmor="ALLOWED" operation="open" с профилем libvirt-<uuid>. Что это значит?', '["Профиль не загружен", "Эти обращения отклонены профилем", "Обращения были разрешены правилом профиля с флагом audit", "Профиль в режиме complain: нарушения разрешены, но записаны"]', 3, 'В режиме complain то, что enforce отклонил бы, записывается как ALLOWED. Флаг audit пишет разрешённые обращения другой строкой AUDIT. После отладки профиль возвращают в enforce командой aa-enforce.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 3, 'Какая команда будет следить за изменением /etc/passwd и пометит события ключом для ausearch?', '["auditctl -w /etc/passwd -p r", "auditctl -w /etc/passwd -p wa -k passwd_changes", "auditctl -k /etc/passwd -w wa", "ausearch -w /etc/passwd"]', 1, 'Ключ -w называет путь, -p wa выбирает запись и смену атрибутов, -k добавляет метку для поиска по ausearch -k. ausearch правил не создаёт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 32, 4, 'Две виртуальные машины работают в домене svirt_t. Что мешает одной из них прочитать образ другой?', '["У них разные номера пользователей", "Права 600 и владелец образа", "Разные пары категорий на процессе и на образе", "Образы лежат на разных блочных устройствах"]', 2, 'В sVirt домен у всех гостей один, а различает их пара категорий вроде c123,c456: процесс может открыть только файл с такой же парой. Владелец и права этого не заменяют.');
